const SUPPORTED_ARIA_ATTRIBUTES = [
  'aria-label',
  'aria-description',
  'aria-expanded',
  'role',
  'aria-describedby',
] as const;

export type AriaAttributes = {
  [_K in (typeof SUPPORTED_ARIA_ATTRIBUTES)[number]]?: string;
};

export function extractAriaAttributes(hostElement: HTMLElement): AriaAttributes {
  const attributes = Array.from(hostElement.attributes).filter((attr) =>
    SUPPORTED_ARIA_ATTRIBUTES.includes(attr.name as (typeof SUPPORTED_ARIA_ATTRIBUTES)[number])
  );
  attributes.forEach((attr) => hostElement.removeAttribute(attr.name));

  return {
    ...attributes.reduce((acc, attr) => ({ ...acc, [attr.name]: attr.value }), {}),
  };
}
